"""Reviewed §1.2 formulas: stable IDs, LaTeX keys and native MathML."""
from .common import mi,mn,mo,sub,frac,power,par,fun,row,sqrt

def prime(value,count=1):return '<msup>'+value+'<mo>'+('′'*count)+'</mo></msup>'
def d(value,variable,order=1):
    return frac((mi('d') if order==1 else power(mi('d'),mn(order)))+value,mi('d')+(mi(variable) if order==1 else power(mi(variable),mn(order))))
def partial(variable,order):return frac((mo('∂') if order==1 else power(mo('∂'),mn(order)))+mi('u'),mo('∂')+(mi(variable) if order==1 else power(mi(variable),mn(order))))
def lines(*items):return '<mtable columnalign="left" rowspacing="0.4em">'+''.join('<mtr><mtd>'+row(item)+'</mtd></mtr>' for item in items)+'</mtable>'
def absolute(value):return row(mo('|'),value,mo('|'))
def exp(value):return power(mi('e'),value)
y,x,t,u=map(mi,['y','x','t','u'])
plus,minus,eq=mo('+'),mo('−'),mo('=')
c1,c2,c3=sub('C',1),sub('C',2),sub('C',3)
sin3=fun('sin',mn(3)+x);cos3=fun('cos',mn(3)+x)
wave=frac(mi('n')+mi('π')+x,mi('L'))
heatwave=frac(mn(3)+mi('π')+x,mi('L'))
rate=frac(power(mi('n'),mn(2))+power(mi('π'),mn(2)),mn(9)+power(mi('L'),mn(2)))
FORMULAS=[]
def add(key,latex,math):FORMULAS.append((key,latex,math))
add('general',r"F(x,y,y',\ldots,y^{(n)})=0",fun('F',x+mo(',')+y+mo(',')+prime(y)+mo(',')+mo('…')+mo(',')+power(y,par(mi('n'))))+eq+mn(0))
add('linear',r"a_n(x)y^{(n)}+\cdots+a_1(x)y'+a_0(x)y=f(x)",sub('a','n')+par(x)+power(y,par(mi('n')))+plus+mo('…')+plus+sub('a',1)+par(x)+prime(y)+plus+sub('a',0)+par(x)+y+eq+fun('f',x))
add('oscillator',r"y''+\omega^2y=\sin x",prime(y,2)+plus+power(mi('ω'),mn(2))+y+eq+fun('sin',x))
add('nonlinear',r"(y')^2+4y=\cos x",power(par(prime(y)),mn(2))+plus+mn(4)+y+eq+fun('cos',x))
add('third',r"x^3y'''+5xy'+6y=e^x",power(x,mn(3))+prime(y,3)+plus+mn(5)+x+prime(y)+plus+mn(6)+y+eq+exp(x))
add('swapped',r"\frac{d^2x}{dy^2}-\sqrt{y}\,x=5",d(x,'y',2)+minus+sqrt(y)+x+eq+mn(5))
add('bessel',r"x^2y''+xy'+(x^2-\nu^2)y=0",power(x,mn(2))+prime(y,2)+plus+x+prime(y)+plus+par(power(x,mn(2))+minus+power(mi('ν'),mn(2)))+y+eq+mn(0))
add('heatType',r"u_{xx}=\frac{1}{\alpha}u_t",partial('x',2)+eq+frac(mn(1),mi('α'))+partial('t',1))
add('poisson',r"u_{xx}+u_{yy}=1",partial('x',2)+plus+partial('y',2)+eq+mn(1))
add('biharmonic',r"u_{xxxx}+2u_{xxyy}+u_{yyyy}=0",partial('x',4)+plus+mn(2)+frac(power(mo('∂'),mn(4))+u,mo('∂')+power(x,mn(2))+mo('∂')+power(y,mn(2)))+plus+partial('y',4)+eq+mn(0))
add('lineOde',r"y'=3",prime(y)+eq+mn(3))
add('lineFamily',r"y=3x+C",y+eq+mn(3)+x+plus+mi('C'))
add('tripleOde',r"y'''=48x",prime(y,3)+eq+mn(48)+x)
add('tripleFamily',r"y=2x^4+\frac{C_1}{2}x^2+C_2x+C_3",y+eq+mn(2)+power(x,mn(4))+plus+frac(c1,mn(2))+power(x,mn(2))+plus+c2+x+plus+c3)
add('fallOde',r"\frac{d^2x}{dt^2}=g",d(x,'t',2)+eq+mi('g'))
add('fallFamily',r"x(t)=C_0+C_1t+\frac{gt^2}{2}",fun('x',t)+eq+sub('C',0)+plus+c1+t+plus+frac(mi('g')+power(t,mn(2)),mn(2)))
add('ivp',r"x(0)=0,\quad x'(0)=v_0",fun('x',mn(0))+eq+mn(0)+mo(',')+prime(x)+par(mn(0))+eq+sub('v',0))
add('bvp',r"x(0)=0,\quad x(T)=L",fun('x',mn(0))+eq+mn(0)+mo(',')+fun('x',mi('T'))+eq+mi('L'))
add('fallBvp',r"x(t)=\left(\frac{L}{T}-\frac{gT}{2}\right)t+\frac{gt^2}{2}",fun('x',t)+eq+par(frac(mi('L'),mi('T'))+minus+frac(mi('g')+mi('T'),mn(2)))+t+plus+frac(mi('g')+power(t,mn(2)),mn(2)))
add('standardIvp',r"y'=f(x,y),\quad y(x_0)=y_0",prime(y)+eq+fun('f',x+mo(',')+y)+mo(',')+fun('y',sub('x',0))+eq+sub('y',0))
add('lipschitz',r"|f(x,y_1)-f(x,y_2)|\leq L|y_1-y_2|",absolute(fun('f',x+mo(',')+sub('y',1))+minus+fun('f',x+mo(',')+sub('y',2)))+mo('≤')+mi('L')+absolute(sub('y',1)+minus+sub('y',2)))
add('existenceBound',r"h=\min\left(a,\frac{b}{M}\right),\quad M=\max_R|f(x,y)|",mi('h')+eq+fun('min',mi('a')+mo(',')+frac(mi('b'),mi('M')))+mo(',')+mi('M')+eq+'<munder><mo>max</mo><mi>R</mi></munder>'+absolute(fun('f',x+mo(',')+y)))
add('singularOde',r"xy'=2y",x+prime(y)+eq+mn(2)+y)
add('singularBranches',r"y(x)=\begin{cases}ax^2,&x\geq0,\\bx^2,&x<0.\end{cases}",fun('y',x)+eq+mo('{')+lines(mi('a')+power(x,mn(2))+mo(',')+x+mo('≥')+mn(0),mi('b')+power(x,mn(2))+mo(',')+x+mo('&lt;')+mn(0)))
add('delayedBranches',r"y_\tau(x)=\begin{cases}0,&x\leq\tau,\\(x-\tau)^2/4,&x>\tau.\end{cases}",sub('y','τ')+par(x)+eq+mo('{')+lines(mn(0)+mo(',')+x+mo('≤')+mi('τ'),frac(power(par(x+minus+mi('τ')),mn(2)),mn(4))+mo(',')+x+mo('>')+mi('τ')))
add('verifyOde',r"y''+3y'-4y=6\sin(3x)",prime(y,2)+plus+mn(3)+prime(y)+minus+mn(4)+y+eq+mn(6)+sin3)
add('odeCandidate',r"y=C_1e^{-4x}+C_2e^x+A\sin(3x)+B\cos(3x)",y+eq+lines(c1+exp(minus+mn(4)+x)+plus+c2+exp(x)+plus+mi('A')+sin3,plus+mi('B')+cos3))
add('odeFirst',r"y'=-4C_1e^{-4x}+C_2e^x+3A\cos(3x)-3B\sin(3x)",prime(y)+eq+lines(minus+mn(4)+c1+exp(minus+mn(4)+x)+plus+c2+exp(x),plus+mn(3)+mi('A')+cos3+minus+mn(3)+mi('B')+sin3))
add('odeSecond',r"y''=16C_1e^{-4x}+C_2e^x-9A\sin(3x)-9B\cos(3x)",prime(y,2)+eq+lines(mn(16)+c1+exp(minus+mn(4)+x)+plus+c2+exp(x),minus+mn(9)+mi('A')+sin3+minus+mn(9)+mi('B')+cos3))
add('odeCoefficients',r"A=-\frac{39}{125},\quad B=-\frac{27}{125}",mi('A')+eq+minus+frac(mn(39),mn(125))+mo(',')+mi('B')+eq+minus+frac(mn(27),mn(125)))
add('odeResidual',r"R(x)=(-13A-9B-6)\sin(3x)+(9A-13B)\cos(3x)",fun('R',x)+eq+lines(par(minus+mn(13)+mi('A')+minus+mn(9)+mi('B')+minus+mn(6))+sin3,plus+par(mn(9)+mi('A')+minus+mn(13)+mi('B'))+cos3))
add('heatCandidate',r"u(x,t)=A\sin\left(\frac{n\pi x}{L}\right)e^{-\lambda t}",fun('u',x+mo(',')+t)+eq+mi('A')+fun('sin',wave)+exp(minus+mi('λ')+t))
add('heatDerivatives',r"u_t=-\lambda u,\quad u_x=A\frac{n\pi}{L}\cos\left(\frac{n\pi x}{L}\right)e^{-\lambda t},\quad u_{xx}=-\left(\frac{n\pi}{L}\right)^2u",lines(partial('t',1)+eq+minus+mi('λ')+u,partial('x',1)+eq+mi('A')+frac(mi('n')+mi('π'),mi('L'))+fun('cos',wave)+exp(minus+mi('λ')+t),partial('x',2)+eq+minus+power(par(frac(mi('n')+mi('π'),mi('L'))),mn(2))+u))
add('verifyHeat',r"u_t=\frac{1}{9}u_{xx}",partial('t',1)+eq+frac(mn(1),mn(9))+partial('x',2))
add('heatDecay',r"\lambda=\frac{n^2\pi^2}{9L^2}",mi('λ')+eq+rate)
add('heatResidual',r"R=u_t-\frac{1}{9}u_{xx}=\left(\frac{n^2\pi^2}{9L^2}-\lambda\right)u",mi('R')+eq+partial('t',1)+minus+frac(mn(1),mn(9))+partial('x',2)+eq+par(rate+minus+mi('λ'))+u)
add('heatConditions',r"u(x,0)=2\sin\left(\frac{3\pi x}{L}\right),\quad u(0,t)=u(L,t)=0",lines(fun('u',x+mo(',')+mn(0))+eq+mn(2)+fun('sin',heatwave),fun('u',mn(0)+mo(',')+t)+eq+fun('u',mi('L')+mo(',')+t)+eq+mn(0)))
add('heatExact',r"u(x,t)=2\sin\left(\frac{3\pi x}{L}\right)e^{-\pi^2t/L^2}",fun('u',x+mo(',')+t)+eq+mn(2)+fun('sin',heatwave)+exp(minus+frac(power(mi('π'),mn(2))+t,power(mi('L'),mn(2)))))
